section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/retro-facilitation-multistyle.json",
  "title": "RetroInstance",
  "type": "object",
  "required": ["retro_date", "next_retro_date", "iteration_length_days", "format", "previous_formats", "selection_rationale", "team_state", "participation", "opening", "previous_actions_review", "action_items", "timebox", "outcome_review"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "format": {"enum": ["mad-sad-glad", "4ls", "sailboat", "lean-coffee", "anonymous-async"]},
    "person": {"type": "string", "minLength": 2, "pattern": "^[^#@]+$", "not": {"pattern": "(?i)^(team|everyone|the team|all|tbd|channel)$"}},
    "counts": {"type": "object", "required": ["cards", "attendance"], "properties": {"cards": {"type": "integer", "minimum": 0}, "attendance": {"type": "integer", "minimum": 0}}}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "retro_date": {"$ref": "#/definitions/date"},
    "next_retro_date": {"$ref": "#/definitions/date"},
    "iteration_length_days": {"type": "integer", "minimum": 5, "maximum": 31},
    "format": {"$ref": "#/definitions/format"},
    "previous_formats": {"type": "array", "maxItems": 2, "items": {"$ref": "#/definitions/format"}},
    "selection_rationale": {"type": "string", "minLength": 20, "not": {"pattern": "(?i)(we always do this|team likes it)"}},
    "team_state": {
      "type": "object",
      "required": ["distribution", "fatigue_signal", "timezones", "all_participants_on_live_call"],
      "properties": {
        "distribution": {"enum": ["async", "hybrid", "in-person"]},
        "fatigue_signal": {"enum": ["fresh", "rotating", "fatigued"]},
        "timezones": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "pattern": "^[A-Za-z_]+/[A-Za-z_/+-]+$|^UTC$"}},
        "all_participants_on_live_call": {"type": "boolean"}
      }
    },
    "participation": {"$ref": "#/definitions/counts"},
    "previous_participation": {"$ref": "#/definitions/counts"},
    "opening": {
      "type": "object",
      "required": ["prime_directive_read", "safety_check", "switched_to_anonymous_input", "non_member_manager_in_discussion"],
      "properties": {
        "prime_directive_read": {"const": true},
        "safety_check": {
          "type": "object",
          "required": ["anonymous", "scale", "median"],
          "properties": {
            "anonymous": {"const": true},
            "scale": {"const": "1-5"},
            "median": {"type": "number", "minimum": 1, "maximum": 5}
          }
        },
        "switched_to_anonymous_input": {"type": "boolean"},
        "non_member_manager_in_discussion": {"const": false}
      },
      "if": {"properties": {"safety_check": {"properties": {"median": {"exclusiveMaximum": 3}}}}},
      "then": {"properties": {"switched_to_anonymous_input": {"const": true}}}
    },
    "previous_actions_review": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["text", "owner", "status", "previously_carried_over"],
        "properties": {
          "text": {"type": "string", "minLength": 5},
          "owner": {"$ref": "#/definitions/person"},
          "status": {"enum": ["done", "not_done_carried_over", "dropped"]},
          "previously_carried_over": {"type": "boolean"},
          "reason": {"type": "string", "minLength": 5}
        },
        "allOf": [
          {"if": {"properties": {"status": {"enum": ["not_done_carried_over", "dropped"]}}}, "then": {"required": ["reason"]}},
          {"if": {"properties": {"previously_carried_over": {"const": true}}}, "then": {"properties": {"status": {"enum": ["done", "dropped"]}}}}
        ]
      }
    },
    "action_items": {
      "type": "array",
      "minItems": 1,
      "maxItems": 3,
      "items": {
        "type": "object",
        "required": ["text", "owner", "evidence_link", "due_date"],
        "properties": {
          "text": {"type": "string", "minLength": 5},
          "owner": {"$ref": "#/definitions/person"},
          "evidence_link": {"type": "string", "pattern": "^https?://\\S+/(issues|pull|pulls|browse|merge_requests|issue)/\\S+$"},
          "due_date": {"$ref": "#/definitions/date"}
        }
      }
    },
    "discussion_notes": {"type": "array", "items": {"type": "string", "minLength": 5}},
    "anonymous_async": {
      "type": "object",
      "required": ["tool_stores_author_identity", "window_start", "window_end", "working_days_in_window_per_timezone", "clustered_before_recap", "attribution_requests", "recap"],
      "properties": {
        "tool_stores_author_identity": {"const": false},
        "window_start": {"$ref": "#/definitions/date"},
        "window_end": {"$ref": "#/definitions/date"},
        "working_days_in_window_per_timezone": {"type": "object", "additionalProperties": {"type": "integer", "minimum": 1}},
        "clustered_before_recap": {"const": true},
        "attribution_requests": {"const": 0},
        "recap": {
          "type": "object",
          "required": ["mode"],
          "properties": {
            "mode": {"enum": ["live_all_timezones", "recorded_open_for_comment"]},
            "comment_window_working_days": {"type": "integer", "minimum": 1}
          },
          "if": {"properties": {"mode": {"const": "recorded_open_for_comment"}}},
          "then": {"required": ["comment_window_working_days"]}
        }
      }
    },
    "lean_coffee": {
      "type": "object",
      "required": ["topics_dot_voted_before_discussion", "topics"],
      "properties": {
        "topics_dot_voted_before_discussion": {"const": true},
        "topics": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["title", "votes", "timebox_minutes", "extensions"],
            "properties": {
              "title": {"type": "string", "minLength": 3},
              "votes": {"type": "integer", "minimum": 0},
              "timebox_minutes": {"type": "integer", "minimum": 1},
              "extensions": {"type": "integer", "minimum": 0, "maximum": 2}
            }
          }
        }
      }
    },
    "timebox": {
      "type": "object",
      "required": ["published_before_start", "minutes", "actual_minutes", "overran"],
      "properties": {
        "published_before_start": {"const": true},
        "minutes": {"type": "integer", "minimum": 15, "maximum": 180},
        "actual_minutes": {"type": "integer", "minimum": 0},
        "overran": {"type": "boolean"}
      }
    },
    "outcome_review": {
      "type": "object",
      "required": ["cadence", "last_run_at"],
      "properties": {
        "cadence": {"enum": ["next-retro", "monthly", "quarterly"]},
        "last_run_at": {"$ref": "#/definitions/date"}
      }
    }
  },
  "allOf": [
    {"if": {"properties": {"team_state": {"properties": {"distribution": {"const": "async"}}}}}, "then": {"properties": {"format": {"const": "anonymous-async"}}}},
    {"if": {"properties": {"format": {"const": "lean-coffee"}}}, "then": {"required": ["lean_coffee"], "properties": {"team_state": {"properties": {"distribution": {"enum": ["in-person", "hybrid"]}, "all_participants_on_live_call": {"const": true}}}}}},
    {"if": {"properties": {"format": {"const": "anonymous-async"}}}, "then": {"required": ["anonymous_async"]}}
  ]
}

example.code:
{
  "retro_date": "2026-05-23",
  "next_retro_date": "2026-06-06",
  "iteration_length_days": 14,
  "format": "anonymous-async",
  "previous_formats": ["sailboat", "4ls"],
  "selection_rationale": "Distribution is async across Europe/Kyiv, Europe/Lisbon and Europe/London, so anonymous-async is the only format that gets the Lisbon outsource cards in; fatigue signal is rotating and the last two retros were sailboat and 4ls, so this also rotates.",
  "team_state": {"distribution": "async", "fatigue_signal": "rotating", "timezones": ["Europe/Kyiv", "Europe/Lisbon", "Europe/London"], "all_participants_on_live_call": false},
  "participation": {"cards": 23, "attendance": 9},
  "previous_participation": {"cards": 17, "attendance": 8},
  "opening": {
    "prime_directive_read": true,
    "safety_check": {"anonymous": true, "scale": "1-5", "median": 4},
    "switched_to_anonymous_input": false,
    "non_member_manager_in_discussion": false
  },
  "previous_actions_review": [
    {"text": "Add a staging smoke test before the Friday deploy", "owner": "Dmytro", "status": "done", "previously_carried_over": false},
    {"text": "Write the on-call handover template", "owner": "Ana", "status": "not_done_carried_over", "previously_carried_over": false, "reason": "Ana was on the incident rotation both weeks; carried over once with a new due date"}
  ],
  "action_items": [
    {"text": "Move the backend deploy window to 16:00 UTC so Lisbon is not deploying after hours", "owner": "Carol", "evidence_link": "https://github.com/acme/platform/issues/482", "due_date": "2026-05-30"},
    {"text": "Write the on-call handover template (carried over)", "owner": "Ana", "evidence_link": "https://github.com/acme/platform/issues/471", "due_date": "2026-06-05"}
  ],
  "discussion_notes": ["Sprint review slot moves earlier for Kyiv; no owner yet, revisit next retro"],
  "anonymous_async": {
    "tool_stores_author_identity": false,
    "window_start": "2026-05-20",
    "window_end": "2026-05-22",
    "working_days_in_window_per_timezone": {"Europe/Kyiv": 2, "Europe/Lisbon": 2, "Europe/London": 2},
    "clustered_before_recap": true,
    "attribution_requests": 0,
    "recap": {"mode": "recorded_open_for_comment", "comment_window_working_days": 1}
  },
  "timebox": {"published_before_start": true, "minutes": 60, "actual_minutes": 55, "overran": false},
  "outcome_review": {"cadence": "next-retro", "last_run_at": "2026-05-23"}
}
